local L={}
function L.get(s)
 if type(s)~='string' then return s end
 if type(TheSentencedDB)=='table' and TheSentencedDB.lang=='en' then return en[s] or s end
 return s
end
function L.language() return type(TheSentencedDB)=='table' and TheSentencedDB.lang=='en' and 'en' or 'pl' end
function L.set(lang) if type(TheSentencedDB)=='table' then TheSentencedDB.lang=(lang=='en' and 'en' or 'pl') end end
NS.Language=L
